// Tests for the mind support modules: the topic rule, the mission calendar line, the reaction test scoring and
// the comparison with the person's own runs. Pure functions only, no browser needed.
// Run: node --test tests/support.test.js. Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import {
  CHECKIN_TOPICS, TOPIC_RULE, topicSignal, topicCounts, offerText, MIND_TIPS, BADGE, pickTips, letterText,
  MISSION_CALENDAR, nextUp, crisisNotice, SUPPORT_TIPS, SRC,
  withEntry, markSent, matchesRisk, plainText, RISK_RULE, TALK_REQUEST_TEXT, TALK_REQUEST_TOPIC, LETTER_TOPIC, isTalkRequest, isLetter,
} from '../src/support.js';
import { RT_RULES, scoreRun, createSession, compareToOwn, median, exampleEarlierRuns } from '../src/reaction-test.js';
import { breathAt, sceneAt, sceneFor, chooseScene, nextSceneAt, clampVolume, soundLevel, volumeText, loopBounds, creditText, problemText, BREAK_SCENES, BREAK_RULES } from '../src/earth-break.js';

const DAY = 24 * 60 * 60 * 1000;
const NOW = new Date('2026-11-15T09:00:00Z');
const day = (n, hour = 7) => new Date(Date.UTC(2026, 10, 15 - n, hour)).toISOString(); // n days before today
const checkin = (n, topics, hour) => ({ time: day(n, hour), topics });

// ---------- F1: topicSignal ----------
test('a topic marked on 3 of the last 7 days is named; the counts follow the placeholder rule', () => {
  const s = topicSignal([checkin(0, ['home']), checkin(2, ['home', 'sleep']), checkin(5, ['home'])], NOW);
  assert.equal(s.id, 'home');
  assert.equal(s.label, 'Missing home');
  assert.equal(s.days, 3);
  assert.equal(s.windowDays, 7);
  assert.equal(s.placeholder, true);
  assert.equal(TOPIC_RULE.minDays, 3);
  assert.match(TOPIC_RULE.text, /open decision/);
});

test('2 days is not enough, and days older than the last 7 do not count', () => {
  assert.equal(topicSignal([checkin(0, ['crew']), checkin(1, ['crew'])], NOW), null);
  assert.equal(topicSignal([checkin(0, ['crew']), checkin(1, ['crew']), checkin(7, ['crew'])], NOW), null, 'day 7 back is the 8th day');
  assert.equal(topicSignal([checkin(0, ['crew']), checkin(1, ['crew']), checkin(6, ['crew'])], NOW).days, 3, 'day 6 back is still inside');
});

test('a topic marked twice on one day counts once, and the last check-in of a day wins', () => {
  const hist = [checkin(0, ['workload'], 6), checkin(0, ['workload'], 8), checkin(1, ['workload']), checkin(3, ['workload'], 6), checkin(3, ['nothing'], 9)];
  assert.equal(topicSignal(hist, NOW), null, 'day 3 was changed to "Nothing in particular" later that day');
  hist.push(checkin(4, ['workload']));
  assert.equal(topicSignal(hist, NOW).days, 3);
});

test('readings saved one topic each at the same time count as one check-in; labels and comma lists are read too', () => {
  const t = (n) => day(n);
  const hist = [
    { time: t(0), value: 'ground' }, { time: t(0), value: 'sleep' },
    { time: t(2), value: ['Mission Control'] },
    { time: t(4), value: 'ground,health' },
  ];
  const s = topicSignal(hist, NOW);
  assert.equal(s.id, 'ground');
  assert.equal(s.days, 3);
  const counts = topicCounts(hist, NOW);
  assert.deepEqual(counts.map((x) => [x.id, x.days]), [['ground', 3], ['sleep', 1], ['health', 1]]);
});

test('"Nothing in particular" never becomes the topic, and readings after now are ignored', () => {
  const hist = [checkin(0, ['nothing']), checkin(1, ['nothing']), checkin(2, ['nothing']), checkin(3, ['nothing'])];
  assert.equal(topicSignal(hist, NOW), null);
  const future = [checkin(0, ['home']), checkin(1, ['home']), { time: '2026-11-15T10:00:00Z', topics: ['home'] }];
  assert.equal(topicSignal(future, NOW), null);
});

test('when two topics qualify, the one with more days wins, then the more recent one', () => {
  const more = [checkin(0, ['crew', 'home']), checkin(1, ['crew', 'home']), checkin(2, ['crew', 'home']), checkin(3, ['home'])];
  assert.equal(topicSignal(more, NOW).id, 'home');
  const recent = [checkin(1, ['crew', 'monotony']), checkin(2, ['crew', 'monotony']), checkin(3, ['crew', 'monotony']), checkin(0, ['monotony'], 8), checkin(4, ['crew'])];
  assert.equal(topicSignal(recent, NOW).id, 'monotony', 'both on 4 days; monotony was marked today');
});

test('bad input gives no topic instead of an error', () => {
  assert.equal(topicSignal(null, NOW), null);
  assert.equal(topicSignal([null, 1, 'x', { time: 'not a date', topics: ['home'] }, { time: day(0), topics: ['no such topic'] }], NOW), null);
  assert.equal(topicSignal([checkin(0, ['home'])], 'not a date'), null);
});

test("the AI offer keeps the owner's words and names the topic", () => {
  const s = { phrase: 'missing home', days: 4, windowDays: 7 };
  const text = offerText('Elly', s);
  assert.equal(text, 'Hey Elly, I noticed from your check-ins that missing home came up on 4 of the last 7 days. How about talking anonymously about what is bothering you? Or, if you wish, I can send the results of these check-ins to the doctor.');
  assert.ok(offerText('Tom').startsWith('Hey Tom, I noticed from your check-ins that the last days have been hard.'));
  assert.equal(CHECKIN_TOPICS.length, 8);
  assert.deepEqual(CHECKIN_TOPICS.map((t) => t.label), ['Missing home', 'Crew', 'Mission Control', 'Workload', 'Sleep', 'Monotony', 'Health', 'Nothing in particular']);
});

// ---------- F2: the cards carry their sources ----------
test('every card has a title, a short text, one of the three badges and a source with title, year and link', () => {
  assert.ok(MIND_TIPS.length >= 10);
  const badges = new Set(Object.values(BADGE));
  for (const t of MIND_TIPS) {
    assert.ok(t.id && t.title && t.text, t.id);
    assert.ok(badges.has(t.badge), `${t.id}: badge ${t.badge}`);
    assert.ok(t.source && t.source.title && Number.isInteger(t.source.year) && /^https:\/\//.test(t.source.url), `${t.id}: source`);
    assert.ok(t.text.split(/[.?!](\s|$)/).filter((x) => x && x.trim()).length <= 2, `${t.id}: one or two sentences`);
  }
  for (const [key, tip] of Object.entries(SUPPORT_TIPS)) {
    assert.ok(tip.title && tip.lines.length && tip.sources.length, key);
    for (const s of tip.sources) assert.ok(s && s.title && s.year && s.url, `${key}: source`);
  }
});

test('the cards are ordered by the signals, and nothing is hidden', () => {
  const home = pickTips({ topic: 'home' });
  assert.equal(home.length, MIND_TIPS.length);
  assert.deepEqual(home.slice(0, 3).map((t) => t.id), ['earth', 'home', 'meal']);
  const sleep = pickTips({ poorSleep: true, topic: 'sleep' });
  assert.deepEqual(sleep.slice(0, 2).map((t) => t.id), ['light', 'surgeon']);
  assert.deepEqual(pickTips({}).map((t) => t.id), MIND_TIPS.map((t) => t.id));
});

// ---------- F4: the private letter ----------
test('the private letter holds only the ticked entries, oldest first', () => {
  const text = letterText([
    { id: 'a', time: '2026-11-14T08:00:00Z', text: 'Second thing', talk: true },
    { id: 'b', time: '2026-11-12T08:00:00Z', text: 'Not for the talk', talk: false },
    { id: 'c', time: '2026-11-10T08:00:00Z', text: 'First thing', talk: true },
  ]);
  assert.match(text, /1\. 10 Nov 2026: First thing\n2\. 14 Nov 2026: Second thing$/);
  assert.doesNotMatch(text, /Not for the talk/);
  assert.equal(letterText([]), '');
});

test('a saved entry is listed once, also when the screen has already handed the list back; a sent letter is not repeated', () => {
  const entry = { id: 'j-1', time: '2026-11-14T08:00:00Z', text: 'Long day.', talk: true };
  const handedBack = [entry];
  const list = withEntry(handedBack, entry);
  assert.equal(list.length, 1);
  assert.equal(withEntry([], entry).length, 1);
  assert.equal((letterText(list).match(/Long day\./g) || []).length, 1, 'the letter names the entry once');
  const sent = markSent([...list, { id: 'j-2', time: '2026-11-13T08:00:00Z', text: 'Kept back.', talk: false }], '2026-11-15T09:00:00Z');
  assert.deepEqual(sent.ids, ['j-1']);
  assert.equal(sent.list[0].talk, false);
  assert.equal(sent.list[0].sentAt, '2026-11-15T09:00:00Z');
  assert.equal(sent.list[1].sentAt, undefined);
  assert.equal(letterText(sent.list), '', 'nothing is left for the next letter');
});

